test('a standalone fictional Calendar preview clears when another tab signs out',async({context,page})=>{
 const other=await context.newPage();await other.goto('/dev-dashboard.html');await expect(other.getByRole('button',{name:'Sign out',exact:true})).toBeVisible();
 await page.evaluate(async()=>{const {mountMacCalendarOpenPreview}=await import('/src/private-mac-calendar-open-ui.mjs');const region=document.createElement('section');region.id='fictional-standalone-calendar';region.innerHTML='<p id="mac-open-status"></p><div id="mac-open-events" data-max-events="5"></div>';document.body.append(region);const now=Date.parse('2026-11-10T18:00:00Z');window.fictionalStandalonePreview=mountMacCalendarOpenPreview({clock:()=>now,client:{status:async()=>({signedIn:true}),clear(){},openMacCalendarPreview:async()=>({source:'Apple Calendar on this Mac',scope:{calendarCount:1,maxEvents:5,startDate:'2026-11-10',endDateExclusive:'2026-12-10',timeZone:'America/New_York',start:Date.parse('2026-11-10T05:00:00Z'),end:Date.parse('2026-12-10T05:00:00Z')},checkedAt:new Date(now).toISOString(),expiresAt:now+100000,events:[{title:'Fictional cross-tab appointment',calendarTitle:'Fictional Calendar',allDay:false,start:'2026-11-10T15:00:00Z',end:'2026-11-10T16:00:00Z'}],complete:true,background:false,persisted:false,savingEnabled:false})}});});
 await expect(page.locator('#mac-open-events')).toContainText('Fictional cross-tab appointment');await other.getByRole('button',{name:'Sign out',exact:true}).click();await expect(page.locator('#mac-open-events')).toBeEmpty();await expect(page.locator('#mac-open-status')).toContainText('Private sign-in changed in another tab');await page.evaluate(()=>window.fictionalStandalonePreview.dispose());await other.close();
});
