test('Calendar Pause keeps keyboard focus after its isolated fictional update',async({page})=>{
 await page.route('**/dev-config.json',async route=>{const response=await route.fetch();await route.fulfill({response,json:{...await response.json(),privateMacCalendarOnOpen:true}});});let releaseOpen;await page.route('**/calendar-source/open-preview',async route=>{await new Promise(resolve=>releaseOpen=resolve);await route.fulfill({status:200,json:{source:'Apple Calendar on this Mac',scope:{calendarCount:1,maxEvents:250,startDate:'2026-11-16',endDateExclusive:'2026-12-16',timeZone:'America/New_York',start:Date.parse('2026-11-16T05:00:00Z'),end:Date.parse('2026-12-16T05:00:00Z')},checkedAt:new Date().toISOString(),expiresAt:Date.now()+100000,events:[],complete:true,background:false,persisted:false,savingEnabled:false}});});let release;await page.route('**/calendar-source/pause',async route=>{await new Promise(resolve=>release=resolve);await route.fulfill({status:200,json:{paused:true}});});await page.goto('/dev-calendar.html');const pause=page.getByRole('button',{name:'Pause calendar checks',exact:true});await expect(page.getByRole('button',{name:'Fetch latest',exact:true})).toBeEnabled();await expect(pause).toBeEnabled();await expect.poll(()=>typeof releaseOpen).toBe('function');await pause.focus();releaseOpen();await expect(page.getByText('No events in this preview window.',{exact:true})).toBeVisible();await expect(pause).toBeFocused();await page.keyboard.press('Enter');await expect(pause).toBeDisabled();expect(await page.evaluate(()=>document.activeElement===document.body)).toBe(true);release();await expect(page.getByText('Apple Calendar checks paused. No events changed.',{exact:true})).toBeVisible();await expect(pause).toBeFocused();
});
