test('saved Calendar rejects stale response timestamps and recovers only on explicit fetch',async({page})=>{
 let reads=0,stale=true;
 await page.route('**/auth/workspace/calendar',async route=>{reads++;const response=await route.fetch();const value=await response.json();await route.fulfill({response,json:stale?{...value,checkedAt:new Date(Date.now()-86400000).toISOString()}:value});});
 await page.goto('/dev-calendar.html');
 await expect(page.getByText('The workspace event list could not be verified. Fetch latest to try again.',{exact:true})).toBeVisible();
 await expect(page.locator('[data-private-calendar-day]')).toHaveCount(0);expect(reads).toBe(1);
 stale=false;await page.getByRole('button',{name:'Fetch latest',exact:true}).click();
 await expect(page.locator('[data-private-calendar-day]').first()).toBeVisible();expect(reads).toBe(2);
});

