 await page.goto('/dev-calendar.html');const calendar=page.getByRole('region',{name:'Workspace Calendar',exact:true}),marker=calendar.locator('li').filter({has:page.getByText(title,{exact:true})});await expect(marker).toContainText('Project target');await expect(marker).toContainText('All day');await expect(marker).toContainText('Work');await expect(marker.getByRole('button')).toHaveCount(0);await expect(page.locator('[data-private-calendar-day="'+today+'"]')).toContainText(title);await page.locator('[data-private-calendar-day="'+today+'"]').click();await expect(marker).toBeVisible();await page.locator('[name="search-query"]').fill(title);await page.getByRole('button',{name:'Apply Calendar filters',exact:true}).click();await expect(calendar.locator('li')).toHaveCount(1);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);
 await page.goto('/dev-tasks.html');await page.getByRole('button',{name:'View projects',exact:true}).click();await page.getByRole('button',{name:'Open project',exact:true}).click();await page.getByLabel('Project visibility',{exact:true}).selectOption('archived');await page.getByRole('button',{name:'Review project',exact:true}).click();await page.getByRole('button',{name:'Approve project save',exact:true}).click();await expect(page.locator('#private-project-editor')).toHaveCount(0);await page.goto('/dev-calendar.html');await expect(page.locator('[data-private-calendar-day]').first()).toBeVisible();await expect(page.getByText(title,{exact:true})).toHaveCount(0);
 await page.goto('/dev-tasks.html');await page.getByRole('button',{name:'View projects',exact:true}).click();await page.getByLabel('Project status filter',{exact:true}).selectOption('archived');await page.getByRole('button',{name:'Apply project filters',exact:true}).click();await page.getByRole('button',{name:'Open project',exact:true}).click();await page.getByLabel('Project visibility',{exact:true}).selectOption('current');await page.getByRole('button',{name:'Review project',exact:true}).click();await page.getByRole('button',{name:'Approve project save',exact:true}).click();await expect(page.locator('#private-project-editor')).toHaveCount(0);await page.goto('/dev-calendar.html');await expect(marker).toBeVisible();await page.getByRole('button',{name:'Sign out',exact:true}).click();await expect(page.getByText(title,{exact:true})).toHaveCount(0);expect(eventWrites).toBe(0);
