test('global project search includes archives and opens exact read-only details only on request',async({page})=>{
 let reads=0;page.on('request',r=>{if(r.url().endsWith('/projects/search-read'))reads++;});
 const title='Fictional duplicate <b>search project';
 for(const archived of [false,true]){
  await page.goto('/dev-tasks.html');await page.getByRole('button',{name:'View projects',exact:true}).click();await page.getByRole('button',{name:'Add a project',exact:true}).click();await page.getByLabel('Project title',{exact:true}).fill(title);await page.getByLabel('Project details',{exact:true}).fill(archived?'Archived exact <script>projectBody=true</script>':'Current exact description');await page.getByLabel('Project area',{exact:true}).selectOption('Work');await page.getByLabel('Project status',{exact:true}).selectOption('Active');if(archived){await page.getByLabel('Project visibility',{exact:true}).selectOption('archived');await page.getByLabel('Project target date (optional)',{exact:true}).fill('2028-02-29');}await page.getByRole('button',{name:'Review project',exact:true}).click();await page.getByRole('button',{name:'Approve project save',exact:true}).click();await expect(page.locator('#private-project-editor')).toHaveCount(0);
 }
 await page.goto('/dev-dashboard.html');await page.getByRole('button',{name:'Browse projects',exact:true}).click();const results=page.getByRole('region',{name:'Title search results',exact:true});await expect(results.getByText(title,{exact:true})).toHaveCount(2);expect(reads).toBe(0);await expect(page.getByText('Current exact description',{exact:true})).toHaveCount(0);
 const archived=results.locator('li').filter({hasText:'Archived'});await expect(archived).toContainText('In Progress');await archived.getByRole('button',{name:'Open project details',exact:true}).click();await expect(page.getByLabel('Project description',{exact:true})).toHaveText('Archived exact <script>projectBody=true</script>');expect(reads).toBe(1);expect(await accessibilityIssues(page)).toEqual([]);const details=page.locator('#private-search-project-details-title').locator('..');await expect(details).toContainText('Read only');await expect(details.getByRole('button')).toHaveCount(1);expect(await page.evaluate(()=>typeof window.projectBody)).toBe('undefined');await page.keyboard.press('Escape');await expect(page.getByLabel('Project description',{exact:true})).toHaveCount(0);await expect(page.locator('[name="search-query"]')).toBeFocused();
 await results.locator('li').filter({hasText:'Current'}).getByRole('button',{name:'Open project details',exact:true}).click();await expect(page.getByLabel('Project description',{exact:true})).toHaveText('Current exact description');await page.getByRole('button',{name:'Close project details',exact:true}).click();await page.locator('[name="search-dateFrom"]').fill('2028-02-29');await page.locator('[name="search-dateTo"]').fill('2028-02-29');await page.getByRole('button',{name:'Search saved titles',exact:true}).click();await expect(results.getByText(title,{exact:true})).toHaveCount(1);await expect(results).toContainText('Archived');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true);await results.getByRole('button',{name:'Open project details',exact:true}).click();await page.getByRole('button',{name:'Sign out',exact:true}).click();await expect(page.getByLabel('Project description',{exact:true})).toHaveCount(0);await expect(page.getByText(title,{exact:true})).toHaveCount(0);
});
